 def find_first_in_sorted(arr, x):
    lo = 0
    hi = len(arr) - 1

    while lo <= hi:
        mid = (lo + hi) // 2

        if x == arr[mid] and (mid == 0 or arr[mid - 1] < x):
            return mid

        elif x <= arr[mid]:
            hi = mid - 1

        else:
            lo = mid + 1

    return -1

print(find_first_in_sorted([3, 4, 5, 5, 5, 5, 6], 5))
print(find_first_in_sorted([3, 4, 5, 5, 5, 5, 6], 7))
print(find_first_in_sorted([3, 4, 5, 5, 5, 5, 6], 2))

